def _seed_feature_flags(apps, schema_editor):
    FeatureFlag = apps.get_model("core", "FeatureFlag")
    for f in _DEFAULT_FLAGS:
        FeatureFlag.objects.get_or_create(
            nombre=f["nombre"],
            agencia=None,
            defaults={
                "enabled": f["enabled"],
                "description": f["description"],
                "rollout_percentage": 100,
            },
        )


def _remove_feature_flags(apps, schema_editor):
    FeatureFlag = apps.get_model("core", "FeatureFlag")
    FeatureFlag.objects.filter(
        nombre__in=[f["nombre"] for f in _DEFAULT_FLAGS], agencia=None
    ).delete()


